/**
 * Policy-maker walkthrough: transcript helper properties, and integrity of the committed transcript
 * and media files (public/media), which are generated by `npm run demo:walkthrough`.
 */
import { describe, expect, it } from 'vitest';
import fc from 'fast-check';
import { readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { activeEntry, mmss, type TranscriptEntry } from '../../src/lib/walkthrough';
import transcript from '../../src/content/policyWalkthrough.json';

const ROOT = join(import.meta.dirname, '..', '..');
const entries: readonly TranscriptEntry[] = transcript;

const sortedTimes = fc
  .uniqueArray(fc.integer({ min: 0, max: 100_000 }), { maxLength: 40 })
  .map((xs) => xs.sort((a, b) => a - b).map((x): TranscriptEntry => ({ t: x / 100, text: 'x' })));

describe('activeEntry', () => {
  it('is the last entry starting at or before t (reference: filter)', () => {
    fc.assert(
      fc.property(sortedTimes, fc.double({ min: -10, max: 1100, noNaN: true }), (es, t) => {
        const expected = es.filter((e) => e.t <= t).length - 1;
        expect(activeEntry(es, t)).toBe(expected);
      }),
    );
  });
  it('is monotone in t', () => {
    fc.assert(
      fc.property(
        sortedTimes,
        fc.double({ min: 0, max: 1000, noNaN: true }),
        fc.double({ min: 0, max: 50, noNaN: true }),
        (es, t, d) => {
          expect(activeEntry(es, t + d)).toBeGreaterThanOrEqual(activeEntry(es, t));
        },
      ),
    );
  });
});

describe('mmss', () => {
  it('round-trips whole seconds', () => {
    fc.assert(
      fc.property(fc.integer({ min: 0, max: 35_999 }), (s) => {
        const [m, ss] = mmss(s).split(':').map(Number);
        expect(ss).toBeLessThan(60);
        expect((m ?? NaN) * 60 + (ss ?? NaN)).toBe(s);
      }),
    );
  });
});

describe('committed walkthrough transcript', () => {
  it('has strictly increasing, non-negative times (also React keys) and non-empty text', () => {
    expect(entries.length).toBeGreaterThan(5);
    entries.forEach((e, i) => {
      expect(e.t).toBeGreaterThanOrEqual(0);
      expect(e.text.trim().length).toBeGreaterThan(0);
      if (i > 0) expect(e.t).toBeGreaterThan(entries[i - 1]?.t ?? Infinity);
    });
  });
  it('covers every step of the method, in order', () => {
    const steps = entries
      .map((e) => /^Step (\d)/.exec(e.step ?? '')?.[1])
      .filter(Boolean)
      .map(Number);
    expect([...new Set(steps)]).toEqual([1, 2, 3, 4, 5, 6]);
  });
  it('fits within the video', () => {
    const mp4 = readFileSync(join(ROOT, 'public/media/policy-walkthrough.mp4'));
    // mvhd: version 0 → timescale at +20, duration at +24 from the box start (ISO/IEC 14496-12).
    const at = mp4.indexOf('mvhd') - 4;
    const duration = mp4.readUInt32BE(at + 24) / mp4.readUInt32BE(at + 20);
    expect(entries.at(-1)?.t ?? Infinity).toBeLessThan(duration);
  });
});

describe('committed walkthrough media', () => {
  const mp4Path = join(ROOT, 'public/media/policy-walkthrough.mp4');
  it('is a web-streamable MP4 (moov before mdat) of a reasonable size', () => {
    const mp4 = readFileSync(mp4Path);
    expect(mp4.subarray(4, 8).toString('latin1')).toBe('ftyp');
    const moov = mp4.indexOf('moov');
    const mdat = mp4.indexOf('mdat');
    expect(moov).toBeGreaterThan(0);
    expect(moov).toBeLessThan(mdat);
    expect(statSync(mp4Path).size).toBeLessThan(12 * 1024 * 1024);
  });
  it('has a JPEG poster', () => {
    const jpg = readFileSync(join(ROOT, 'public/media/policy-walkthrough.jpg'));
    expect([...jpg.subarray(0, 3)]).toEqual([0xff, 0xd8, 0xff]);
  });
});
